    message: string;
    contactId?: string;
    channel?: string;
    context?: UnknownRecord;
    executeTools?: boolean;
  }): Promise<{
    reply?: string;
    response?: string;
    actions: ActionEntry[];
    intent: string;
    confidence: number;
  }> {
    const result = await this.processMessage({
      workspaceId: params.workspaceId,
      contactId: params.contactId || "",
      phone: params.phone,
      message: params.message,
      context: {
        channel: params.channel || "whatsapp",
        executeTools: params.executeTools !== false,
        ...(params.context || {}),
      },
    });

    return {
      actions: result.actions,
      intent: result.intent,
      confidence: result.confidence,
      ...(result.response !== undefined
        ? { reply: result.response, response: result.response }
        : {}),
    };
  }

  async processMessage(params: {
    allowedTools?: string[];
    predecidedActions?: PredecidedAction[];
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
  }): Promise<{
    actions: ActionEntry[];
    response?: string;
    intent: string;
    confidence: number;
  }> {
    return processUnifiedAgentMessage(
      {
        abiBuilder: this.abiBuilder,
        actions: this.actions,
        ctx: this.ctx,
        buildAgentRuntimeContext: this.buildAgentRuntimeContext.bind(this),
        executeToolAction: this.executeToolAction.bind(this),
        fallbackBrainModel: this.fallbackBrainModel,
        fallbackWriterModel: this.fallbackWriterModel,
        logger: this.logger,
        openai: this.openai,
        planLimits: this.planLimits,
        primaryBrainModel: this.primaryBrainModel,
        prisma: this.prisma,
        recordAgentRuntimeTurn: this.recordAgentRuntimeTurn.bind(this),
        response: this.response,
        writerModel: this.writerModel,
      },
      params,
    );
  }

  /**
   * Public API: execute a single named tool directly.
   */
  async executeTool(
    tool: string,
    args: ToolArgs,
    ctx: { workspaceId: string; contactId?: string; phone?: string },
  ): Promise<unknown> {
    return this.executeToolAction(
      ctx.workspaceId,
      ctx.contactId || "",
      ctx.phone || "",
      tool,
      args,
    );
  }

  /** Build quoted reply plan (delegates to response service). */
  async buildQuotedReplyPlan(params: {
    workspaceId: string;
    contactId?: string;
    phone: string;
    draftReply: string;
    customerMessages: Array<{ content: string; quotedMessageId: string }>;
  }): Promise<Array<{ quotedMessageId: string; text: string }>> {
    return this.response.buildQuotedReplyPlan(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      this.planLimits,
      params,
    );
  }

  private async executeToolAction(
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: ToolArgs,
    context?: UnknownRecord,
  ): Promise<unknown> {
    return this.toolRouter.executeToolAction(workspaceId, contactId, phone, tool, args, context);
  }

  private async buildAgentRuntimeContext(params: {
    workspaceId: string;
    channel: string;
    message: string;
    contactId?: string;
    allowedTools?: string[];
  }): Promise<{ systemPromptBlock: string }> {
    if (!this.agentRuntime) {
      return { systemPromptBlock: "" };
    }
    return this.agentRuntime.buildContext(params);
  }

  private async recordAgentRuntimeTurn(params: {
    workspaceId: string;
    channel: string;
    userMessage: string;
    assistantMessage?: string;
    contactId?: string;
    intent?: string;
    confidence?: number;
    actions?: Array<{ toolName: string; success: boolean; result?: unknown }>;
  }): Promise<void> {
    await this.agentRuntime?.recordTurnOutcome(params);
  }
}"
}

